
const posts = [
    {
            user: "mariana",
                    avatar: "https://i.pravatar.cc/100?img=11",
                            image: "https://images.unsplash.com/photo-1470770841072-f978cf4d019e?w=800",
                                    description: "Que lugar incrível! 🌄❤️",
                                            likes: 1245
                                                },
                                                    {
                                                            user: "pedro",
                                                                    avatar: "https://i.pravatar.cc/100?img=13",
                                                                            image: "https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?w=800",
                                                                                    description: "Aproveitando cada momento! ☀️",
                                                                                            likes: 856
                                                                                                },
                                                                                                    {
                                                                                                            user: "carolina",
                                                                                                                    avatar: "https://i.pravatar.cc/100?img=14",
                                                                                                                            image: "https://images.unsplash.com/photo-1490750967868-88aa4486c946?w=800",
                                                                                                                                    description: "Pequenos detalhes fazem a diferença 🌸",
                                                                                                                                            likes: 2340
                                                                                                                                                }
                                                                                                                                                ];

                                                                                                                                                const suggestions = [
                                                                                                                                                    {
                                                                                                                                                            user: "gabriel",
                                                                                                                                                                    avatar: "https://i.pravatar.cc/100?img=20"
                                                                                                                                                                        },
                                                                                                                                                                            {
                                                                                                                                                                                    user: "fernanda",
                                                                                                                                                                                            avatar: "https://i.pravatar.cc/100?img=25"
                                                                                                                                                                                                },
                                                                                                                                                                                                    {
                                                                                                                                                                                                            user: "rafael",
                                                                                                                                                                                                                    avatar: "https://i.pravatar.cc/100?img=30"
                                                                                                                                                                                                                        }
                                                                                                                                                                                                                        ];


                                                                                                                                                                                                                        // CRIAR PUBLICAÇÕES

                                                                                                                                                                                                                        const feed = document.getElementById("feed");

                                                                                                                                                                                                                        posts.forEach((post, index) => {

                                                                                                                                                                                                                            const article = document.createElement("article");

                                                                                                                                                                                                                                article.className = "post";

                                                                                                                                                                                                                                    article.innerHTML = `
                                                                                                                                                                                                                                            <div class="post-header">

                                                                                                                                                                                                                                                        <img src="${post.avatar}" class="avatar">

                                                                                                                                                                                                                                                                    <strong class="text-sm">${post.user}</strong>

                                                                                                                                                                                                                                                                                <span class="ml-auto cursor-pointer">•••</span>

                                                                                                                                                                                                                                                                                        </div>

                                                                                                                                                                                                                                                                                                <img src="${post.image}" class="post-image">

                                                                                                                                                                                                                                                                                                        <div class="post-actions">

                                                                                                                                                                                                                                                                                                                    <button class="action-btn like-btn" data-index="${index}">
                                                                                                                                                                                                                                                                                                                                    ♡
                                                                                                                                                                                                                                                                                                                                                </button>

                                                                                                                                                                                                                                                                                                                                                            <button class="action-btn comment-btn" data-index="${index}">
                                                                                                                                                                                                                                                                                                                                                                            💬
                                                                                                                                                                                                                                                                                                                                                                                        </button>

                                                                                                                                                                                                                                                                                                                                                                                                    <button class="action-btn">
                                                                                                                                                                                                                                                                                                                                                                                                                    ➤
                                                                                                                                                                                                                                                                                                                                                                                                                                </button>

                                                                                                                                                                                                                                                                                                                                                                                                                                            <button class="action-btn ml-auto save-btn">
                                                                                                                                                                                                                                                                                                                                                                                                                                                            ♧
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </button>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <strong class="text-sm" id="likes-${index}">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ${post.likes} curtidas
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </strong>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <p class="text-sm mt-2">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <strong>${post.user}</strong>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ${post.description}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </p>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div id="comments-${index}" class="text-sm mt-2"></div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <form class="comment-form flex gap-2 mt-3" data-index="${index}">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <input
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                type="text"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                placeholder="Adicione um comentário..."
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                class="flex-1 outline-none text-sm"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            >

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <button class="text-blue-500 font-bold text-sm">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        Publicar
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </form>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                `;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    feed.appendChild(article);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // CURTIDAS

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    document.querySelectorAll(".like-btn").forEach(button => {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        button.addEventListener("click", () => {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const index = button.dataset.index;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const liked = button.classList.toggle("liked");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                button.innerHTML = liked ? "♥" : "♡";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        posts[index].likes += liked ? 1 : -1;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                document.getElementById(`likes-${index}`)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .textContent = `${posts[index].likes} curtidas`;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // COMENTÁRIOS

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                document.querySelectorAll(".comment-form").forEach(form => {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    form.addEventListener("submit", event => {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            event.preventDefault();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const input = form.querySelector("input");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const index = form.dataset.index;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (input.value.trim() === "") return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const comment = document.createElement("p");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    comment.className = "mt-2";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const username = document.createElement("strong");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    username.textContent = "seu_usuario ";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            comment.appendChild(username);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    comment.appendChild(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                document.createTextNode(input.value.trim())
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                document.getElementById(`comments-${index}`)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .appendChild(comment);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    input.value = "";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // SALVAR PUBLICAÇÕES

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        document.querySelectorAll(".save-btn").forEach(button => {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            button.addEventListener("click", () => {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const saved = button.classList.toggle("liked");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            button.innerHTML = saved ? "🔖" : "♧";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // SUGESTÕES DE PERFIS

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const suggestionsList = document.getElementById("suggestions-list");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                suggestions.forEach(person => {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const div = document.createElement("div");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        div.className = "flex items-center gap-3";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const avatar = document.createElement("img");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                avatar.src = person.avatar;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    avatar.className = "avatar";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const name = document.createElement("strong");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            name.className = "text-sm flex-1";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                name.textContent = person.user;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const follow = document.createElement("button");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        follow.className = "text-blue-500 text-xs font-bold";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            follow.textContent = "Seguir";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                follow.addEventListener("click", () => {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const following = follow.textContent === "Seguindo";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                follow.textContent = following ? "Seguir" : "Seguindo";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        follow.classList.toggle("text-gray-500");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                div.append(avatar, name, follow);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    suggestionsList.appendChild(div);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    